<?php
namespace Tests\Feature;
use App\Models\Customer; use App\Models\Organization; use App\Models\Ticket; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
final class TicketCrudTest extends TestCase { use RefreshDatabase; private function customer():Customer{$org=Organization::create(['name'=>'Test']);return Customer::create(['organization_id'=>$org->id,'name'=>'Customer','email'=>'customer@test']);}
 public function test_complete_crud_contract_and_request_id():void{$customer=$this->customer();$created=$this->withHeader('X-Request-ID','crud-test')->postJson('/api/tickets',['organization_id'=>$customer->organization_id,'customer_id'=>$customer->id,'subject'=>'Observable CRUD']);$created->assertCreated()->assertHeader('X-Request-ID','crud-test');$id=$created->json('ticket.id');$this->getJson("/api/tickets/$id")->assertOk()->assertJsonPath('ticket.subject','Observable CRUD');$this->patchJson("/api/tickets/$id",['subject'=>'Updated'])->assertOk()->assertJsonPath('ticket.subject','Updated');$this->assertDatabaseHas('tickets',['id'=>$id,'subject'=>'Updated']);$this->deleteJson("/api/tickets/$id")->assertNoContent();$this->assertDatabaseMissing('tickets',['id'=>$id]);}
 public function test_validation_and_relationship_scope():void{$customer=$this->customer();$other=Customer::create(['organization_id'=>Organization::create(['name'=>'Other'])->id,'name'=>'Other','email'=>'other@test']);$this->postJson('/api/tickets',['organization_id'=>$customer->organization_id,'customer_id'=>$other->id,'subject'=>'Leak'])->assertUnprocessable()->assertJsonValidationErrors('customer_id');$this->postJson('/api/tickets',['organization_id'=>$customer->organization_id,'customer_id'=>$customer->id,'subject'=>''])->assertUnprocessable()->assertJsonValidationErrors('subject');}
 public function test_route_failures_are_distinct():void{$this->postJson('/api/tickets/1')->assertMethodNotAllowed();$this->getJson('/api/ticket/1')->assertNotFound();$this->getJson('/api/tickets/not-a-number')->assertNotFound();}
}
